// ========================================
// データストレージ（LocalStorage + Firebase対応）
// ========================================

const DB = {
    // キー名
    KEYS: {
        USERS: 'pms_users',
        BOM: 'pms_bom',
        ORDERS: 'pms_orders',
        RATES: 'pms_rates',
        DEFECTS: 'pms_defects',
        PROGRESS_HISTORY: 'pms_progress_history',
        CURRENT_USER: 'pms_current_user',
        // 在庫管理
        INV_PRODUCTS: 'pms_inv_products',      // 商品マスタ
        INV_LOGS: 'pms_inv_logs',              // 棚卸ログ
        INV_MONTHLY: 'pms_inv_monthly',        // 月次在庫データ
        INV_SCAN_TEMP: 'pms_inv_scan_temp',    // 棚卸仮スキャンデータ
        // 掲示板
        NOTICE: 'pms_notice',                  // 連絡事項
        // バックアップ
        BACKUPS: 'pms_backups'                 // バックアップ履歴
    },

    // Firebaseキーへの変換（pms_プレフィックスを除去）
    toFirebaseKey(key) {
        return key.replace('pms_', '');
    },

    // キャッシュ（Firebase用）
    _cache: {},
    _listeners: {},
    _loaded: {}, // Firebaseからの初回読み込み完了フラグ

    // 初期データ
    init() {
        // Firebase接続時はリスナーを設定
        if (typeof useFirebase !== 'undefined' && useFirebase && firebaseDB) {
            this.initFirebase();
            setTimeout(() => {
                this.applyLatestBom();
            }, 3000);
            return;
        }

        // Firebase未設定時はローカルストレージで初期化
        this.initLocalStorage();
        this.applyLatestBom();
    },

    // LocalStorage初期化
    initLocalStorage() {
        console.log('📦 ローカルストレージモードで起動');

        // ユーザーに通知（Firebaseが設定されていないことへの注意喚起）
        setTimeout(() => {
            toast('⚠️ 現在オフラインモード（自分のみ）です。<br>共有するには設定が必要です。', 'warning', 10000);
        }, 2000);

        // ユーザー
        if (!localStorage.getItem(this.KEYS.USERS)) {
            this.save(this.KEYS.USERS, [
                { id: 1, username: 'admin', password: 'admin123', displayName: '管理者', role: 'admin', department: '管理部' },
                { id: 2, username: 'worker', password: 'worker123', displayName: '作業者A', role: 'worker', department: '製造部' }
            ]);
        }

        // BOM（サンプル）
        if (!localStorage.getItem(this.KEYS.BOM)) {
            this.save(this.KEYS.BOM, [
                {
                    id: 1,
                    category: 'PAO',
                    productName: 'PAO1012BL',
                    bomName: 'PaO1012BL(正面)',
                    partCode: 'FR1012BL',
                    processes: ['芯材カット', '面材カット', '芯組', 'フラッシュ', 'ランニングソー', 'エッヂバンダー', '仕上・梱包']
                },
                {
                    id: 2,
                    category: 'PAO',
                    productName: 'PAO1012BL',
                    bomName: 'PaO1012BL(側面L)',
                    partCode: 'SL1012BL',
                    processes: ['芯材カット', '面材カット', '芯組', 'フラッシュ', 'ランニングソー', '仕上・梱包']
                },
                {
                    id: 3,
                    category: 'PAO',
                    productName: 'PAO1012BL',
                    bomName: 'PaO1012BL(側面R)',
                    partCode: 'SR1012BL',
                    processes: ['芯材カット', '面材カット', '芯組', 'フラッシュ', 'ランニングソー', '仕上・梱包']
                }
            ]);
        }

        // 指示書（サンプル）
        if (!localStorage.getItem(this.KEYS.ORDERS)) {
            const today = new Date().toISOString().split('T')[0];
            const nextWeek = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString().split('T')[0];

            this.save(this.KEYS.ORDERS, [
                {
                    id: 1,
                    orderNo: 'TK-2026-001',
                    projectName: '○○ビル改装工事',
                    productName: 'PAO1012BL',
                    quantity: 5,
                    startDate: today,
                    dueDate: nextWeek,
                    color: 'ホワイト',
                    items: [
                        { id: 1, bomName: 'PaO1012BL(正面)', partCode: 'FR1012BL', processes: ['芯材カット', '面材カット', '芯組', 'フラッシュ', 'ランニングソー', 'エッヂバンダー', '仕上・梱包'], completed: [] },
                        { id: 2, bomName: 'PaO1012BL(側面L)', partCode: 'SL1012BL', processes: ['芯材カット', '面材カット', '芯組', 'フラッシュ', 'ランニングソー', '仕上・梱包'], completed: [] },
                        { id: 3, bomName: 'PaO1012BL(側面R)', partCode: 'SR1012BL', processes: ['芯材カット', '面材カット', '芯組', 'フラッシュ', 'ランニングソー', '仕上・梱包'], completed: [] }
                    ]
                }
            ]);
        }

        // 賃率（localStorageモードのみ。Firebaseモードは ensureInitialData で処理）
        const isFirebaseMode = typeof useFirebase !== 'undefined' && useFirebase;
        if (!isFirebaseMode) {
            const defaultRates = [
                { id: 1, rateCode: '第二製造課基材係', department: '製造部', section: '第二製造課', subsection: '基材係', monthlyRate: 480855, dailyRate: 22898, hourlyRate: 2862, minuteRate: 47.7, secondRate: 0.8 },
                { id: 2, rateCode: '第二製造課加工係', department: '製造部', section: '第二製造課', subsection: '加工係', monthlyRate: 487041, dailyRate: 23192, hourlyRate: 2899, minuteRate: 48.3, secondRate: 0.8 },
                { id: 3, rateCode: '第二製造課梱包仕上係', department: '製造部', section: '第二製造課', subsection: '梱包仕上係', monthlyRate: 360695, dailyRate: 17176, hourlyRate: 2147, minuteRate: 35.8, secondRate: 0.6 }
            ];
            const existingRates = localStorage.getItem(this.KEYS.RATES);
            if (!existingRates) {
                this.save(this.KEYS.RATES, defaultRates);
            } else {
                try {
                    const parsed = JSON.parse(existingRates);
                    const isOldFormat = Array.isArray(parsed) && parsed.length > 0 &&
                        (parsed[0].rate !== undefined ||
                            parsed[0].secondRate === undefined ||
                            parsed[0].rateCode === 'A01');
                    if (isOldFormat) {
                        console.log('🔄 賃率データをマイグレーション: 旧形式 → 新形式');
                        this.save(this.KEYS.RATES, defaultRates);
                    }
                } catch (e) {
                    this.save(this.KEYS.RATES, defaultRates);
                }
            }
        }

        // 不良品
        if (!localStorage.getItem(this.KEYS.DEFECTS)) {
            this.save(this.KEYS.DEFECTS, []);
        }

        // 進捗履歴
        if (!localStorage.getItem(this.KEYS.PROGRESS_HISTORY)) {
            this.save(this.KEYS.PROGRESS_HISTORY, []);
        }

        // 在庫：商品マスタ（棚卸原簿マスタ初期展開）
        if (!localStorage.getItem(this.KEYS.INV_PRODUCTS)) {
            if (typeof getGenboMasterProducts === 'function') {
                this.save(this.KEYS.INV_PRODUCTS, getGenboMasterProducts());
            } else {
                this.save(this.KEYS.INV_PRODUCTS, [
                    { id: 'N01000000000001', identCode: '01-001', name: 'パーティクルボード 18mm', category: '01', price: 3500, isFixed: false }
                ]);
            }
        }

        // 在庫：棚卸ログ
        if (!localStorage.getItem(this.KEYS.INV_LOGS)) {
            this.save(this.KEYS.INV_LOGS, []);
        }

        // 在庫：月次データ
        if (!localStorage.getItem(this.KEYS.INV_MONTHLY)) {
            this.save(this.KEYS.INV_MONTHLY, []);
        }

        // 在庫：棚卸仮スキャンデータ
        if (!localStorage.getItem(this.KEYS.INV_SCAN_TEMP)) {
            this.save(this.KEYS.INV_SCAN_TEMP, []);
        }

        // 掲示板（連絡事項）
        if (!localStorage.getItem(this.KEYS.NOTICE)) {
            this.save(this.KEYS.NOTICE, [{ id: 1, text: "本日の連絡事項はありません", updatedAt: new Date().toISOString() }]);
        }
    },

    // Firebase初期化
    initFirebase() {
        console.log('🔥 Firebaseモードで起動');

        // 接続状態監視
        firebaseDB.ref('.info/connected').on('value', (snap) => {
            if (snap.val() === true) {
                console.log('✅ Firebase接続完了');
                toast('☁️ サーバーに接続しました（共有有効）', 'success');
            } else {
                console.warn('⚠️ Firebase未接続');
                // 切断時（または初期接続失敗時）
                // toast('⚠️ サーバー接続が切れています', 'warning');
            }
        });

        // 各データタイプにリスナーを設定
        const dataKeys = [
            this.KEYS.USERS, this.KEYS.BOM, this.KEYS.ORDERS,
            this.KEYS.RATES, this.KEYS.DEFECTS, this.KEYS.PROGRESS_HISTORY,
            this.KEYS.INV_PRODUCTS, this.KEYS.INV_LOGS, this.KEYS.INV_MONTHLY,
            this.KEYS.BACKUPS, this.KEYS.INV_SCAN_TEMP, this.KEYS.NOTICE
        ];

        dataKeys.forEach(key => {
            const fbKey = this.toFirebaseKey(key);

            // リアルタイムリスナー
            firebaseDB.ref(fbKey).on('value', (snapshot) => {
                const data = snapshot.val();
                let parsedData = data ? (Array.isArray(data) ? data : Object.values(data)) : [];
                this._cache[key] = parsedData.filter(item => item !== null);
                this._loaded[key] = true; // 同期完了フラグをセット
                localStorage.setItem(key, typeof LZString !== 'undefined' ? LZString.compressToUTF16(JSON.stringify(this._cache[key])) : JSON.stringify(this._cache[key])); // 常にローカルにバックアップ
                console.log(`🔄 ${fbKey} 更新:`, this._cache[key].length, '件');

                // UI更新（定義されている場合）
                if (typeof refreshCurrentPage === 'function') {
                    refreshCurrentPage();
                }
            }, (error) => {
                console.error(`❌ ${fbKey} 読み込みエラー:`, error);
                // エラー時もロックを解除してローカルキャッシュで動作可能にする
                this._loaded[key] = true;
            });
        });

        // 初期データがない場合は作成
        setTimeout(() => {
            this.ensureInitialData();
        }, 2000);

        // 自動バックアップチェック（データ読み込み後）
        setTimeout(() => {
            this.checkAutoBackup();
        }, 5000);
    },

    // Firebase初期データ確認
    ensureInitialData() {
        const defaultRates = [
            { id: 1, rateCode: '第二製造課基材係', department: '製造部', section: '第二製造課', subsection: '基材係', monthlyRate: 480855, dailyRate: 22898, hourlyRate: 2862, minuteRate: 47.7, secondRate: 0.8 },
            { id: 2, rateCode: '第二製造課加工係', department: '製造部', section: '第二製造課', subsection: '加工係', monthlyRate: 487041, dailyRate: 23192, hourlyRate: 2899, minuteRate: 48.3, secondRate: 0.8 },
            { id: 3, rateCode: '第二製造課梱包仕上係', department: '製造部', section: '第二製造課', subsection: '梱包仕上係', monthlyRate: 360695, dailyRate: 17176, hourlyRate: 2147, minuteRate: 35.8, secondRate: 0.6 }
        ];

        if (typeof useFirebase !== 'undefined' && useFirebase && firebaseDB) {
            firebaseDB.ref(this.toFirebaseKey(this.KEYS.USERS)).once('value').then(snap => {
                if (!snap.exists() || !snap.val() || Object.keys(snap.val()).length === 0) {
                    this.save(this.KEYS.USERS, [
                        { id: 1, username: 'admin', password: 'admin123', displayName: '管理者', role: 'admin', department: '管理部' },
                        { id: 2, username: 'worker', password: 'worker123', displayName: '作業者A', role: 'worker', department: '製造部' }
                    ]);
                }
            });

            firebaseDB.ref(this.toFirebaseKey(this.KEYS.RATES)).once('value').then(snap => {
                let needsInit = false;
                if (!snap.exists() || !snap.val() || Object.keys(snap.val()).length === 0) {
                    needsInit = true;
                } else {
                    const data = snap.val();
                    const rates = Array.isArray(data) ? data : Object.values(data);
                    if (rates.length > 0 && (
                        rates[0].secondRate === undefined ||
                        rates[0].rate !== undefined ||
                        rates[0].rateCode === 'A01'
                    )) {
                        needsInit = true;
                    }
                }

                if (needsInit) {
                    console.log('🔄 ensureInitialData: 賃率データを初期化/マイグレーション');
                    this.save(this.KEYS.RATES, defaultRates);
                }
            });
        } else {
            if (this.get(this.KEYS.USERS).length === 0) {
                this.save(this.KEYS.USERS, [
                    { id: 1, username: 'admin', password: 'admin123', displayName: '管理者', role: 'admin', department: '管理部' },
                    { id: 2, username: 'worker', password: 'worker123', displayName: '作業者A', role: 'worker', department: '製造部' }
                ]);
            }

            // 賃率: 空 OR 旧形式なら初期値を設定
            const rates = this.get(this.KEYS.RATES);
            const needsInit = rates.length === 0 ||
                (rates.length > 0 && (
                    rates[0].secondRate === undefined ||
                    rates[0].rate !== undefined ||
                    rates[0].rateCode === 'A01'
                ));

            if (needsInit) {
                console.log('🔄 ensureInitialData: 賃率データを初期化/マイグレーション');
                this.save(this.KEYS.RATES, defaultRates);
            }
        }
        
        // 既存スキャンデータの救済（INV_PRODUCTS 内から INV_SCAN_TEMP へ抽出・移行）
        setTimeout(() => {
            this.migrateTempScansFromProducts();
        }, 3000);
    },

    // 既存の埋め込みスキャンデータを INV_SCAN_TEMP に移行する（データロスト防止）
    migrateTempScansFromProducts() {
        if (typeof useFirebase !== 'undefined' && useFirebase && (!this._loaded[this.KEYS.INV_PRODUCTS] || !this._loaded[this.KEYS.INV_SCAN_TEMP])) {
            // Firebase読込待機
            setTimeout(() => this.migrateTempScansFromProducts(), 1000);
            return;
        }

        const products = this.get(this.KEYS.INV_PRODUCTS) || [];
        const tempScans = this.get(this.KEYS.INV_SCAN_TEMP) || [];
        let migratedCount = 0;
        let needsProductSave = false;

        products.forEach(p => {
            if (p.tempQty !== undefined && p.tempQty !== null) {
                const scanId = p.tempId || (Date.now() + "_" + p.id);
                // 既に存在しない場合のみ追加
                if (!tempScans.some(s => s.id === scanId)) {
                    tempScans.push({
                        id: scanId,
                        productId: p.id,
                        quantity: p.tempQty,
                        worker: p.tempWorker || '',
                        workerName: p.tempWorkerName || '',
                        timestamp: p.tempTimestamp || new Date().toISOString(),
                        month: p.tempMonth || '',
                        type: 'count_temp'
                    });
                    migratedCount++;
                }
                // products から削除
                delete p.tempQty;
                delete p.tempWorker;
                delete p.tempWorkerName;
                delete p.tempTimestamp;
                delete p.tempMonth;
                delete p.tempId;
                needsProductSave = true;
            }
        });

        if (migratedCount > 0 || needsProductSave) {
            console.log(`🔄 ${migratedCount}件の仮スキャンデータを INV_SCAN_TEMP に移行・救済しました。`);
            this.save(this.KEYS.INV_SCAN_TEMP, tempScans);
            this.save(this.KEYS.INV_PRODUCTS, products);
        }
    },

    // 保存（全置換 - 初期化時など限定）
    save(key, data) {
        // Firebase同期前の空データ上書きを防止
        if (typeof useFirebase !== 'undefined' && useFirebase && !this._loaded[key]) {
            console.warn(`⚠️ ${key} の保存をスキップ: Firebaseからの初回読み込みが未完了です`);
            return Promise.resolve(false);
        }

        if (typeof useFirebase !== 'undefined' && useFirebase && firebaseDB && key !== this.KEYS.CURRENT_USER) {
            const fbKey = this.toFirebaseKey(key);
            this._cache[key] = data;
            // 常にLocalStorageにもキャッシュを保存（オフライン・権限エラー対策の強力なフォールバック）
            localStorage.setItem(key, typeof LZString !== 'undefined' ? LZString.compressToUTF16(JSON.stringify(data)) : JSON.stringify(data));
            return firebaseDB.ref(fbKey).set(data)
                .then(() => {
                    console.log(`💾 ${fbKey} 保存完了`);
                    return true;
                })
                .catch(err => {
                    console.error(`❌ ${fbKey} 保存エラー:`, err);
                    throw err;
                });
        } else {
            localStorage.setItem(key, typeof LZString !== 'undefined' ? LZString.compressToUTF16(JSON.stringify(data)) : JSON.stringify(data));
            if (typeof refreshCurrentPage === 'function') refreshCurrentPage();
            return Promise.resolve(true);
        }
    },

    // 棚卸仮スキャンデータ（レガシーのINV_LOGSと、新しいINV_PRODUCTSの両方をマージして返す）
    getTempScans() {
        const logs = this.get(this.KEYS.INV_LOGS) || [];
        const legacyScans = logs.filter(log => log && log.type === 'count_temp');
        
        const products = this.get(this.KEYS.INV_PRODUCTS) || [];
        const newScans = products
            .filter(p => p && p.tempQty !== undefined && p.tempQty !== null)
            .map(p => ({
                id: p.tempId || p.id,
                productId: p.id,
                quantity: p.tempQty,
                worker: p.tempWorker,
                workerName: p.tempWorkerName,
                timestamp: p.tempTimestamp,
                month: p.tempMonth,
                type: 'count_temp'
            }));

        const dedicatedTempScans = this.get(this.KEYS.INV_SCAN_TEMP) || [];

        // 【バグ修正】productId単体ではなく「month + productId」でマージし、過去月データが当月データを上書き消失させる不具合を防止
        const mergedMap = {};
        const putScan = (scan) => {
            if (!scan || !scan.productId) return;
            const m = scan.month || (scan.timestamp ? String(scan.timestamp).substring(0, 7) : '');
            const key = m + '__' + scan.productId;
            mergedMap[key] = Object.assign({}, scan, { month: m || scan.month });
        };

        legacyScans.forEach(putScan);
        dedicatedTempScans.forEach(putScan);
        newScans.forEach(putScan); // INV_PRODUCTSの最新状態を優先しつつ統合
        
        return Object.values(mergedMap);
    },

    saveTempScan(productId, quantity, worker, workerName, timestamp, month, terminalId) {
        const targetMonth = month || (timestamp ? String(timestamp).substring(0, 7) : new Date().toISOString().substring(0, 7));
        const scanId = Date.now() + "_" + Math.random().toString(36).substr(2, 9);
        const newScan = {
            id: scanId,
            productId: productId,
            quantity: quantity,
            worker: worker || 'unknown',
            workerName: workerName || worker || '不明な作業者',
            timestamp: timestamp || new Date().toISOString(),
            month: targetMonth,
            terminalId: terminalId || '',
            type: 'count_temp'
        };

        // 1. INV_PRODUCTS 側の仮登録プロパティを同期更新
        const products = this.get(this.KEYS.INV_PRODUCTS) || [];
        const prodIndex = products.findIndex(p => p && String(p.id).toUpperCase() === String(productId).toUpperCase());
        if (prodIndex !== -1) {
            products[prodIndex].tempQty = quantity;
            products[prodIndex].tempWorker = newScan.worker;
            products[prodIndex].tempWorkerName = newScan.workerName;
            products[prodIndex].tempTimestamp = newScan.timestamp;
            products[prodIndex].tempMonth = targetMonth;
            products[prodIndex].tempId = scanId;
            this.save(this.KEYS.INV_PRODUCTS, JSON.parse(JSON.stringify(products)));
        }

        // 2. INV_SCAN_TEMP 側を同期更新
        const tempScans = this.get(this.KEYS.INV_SCAN_TEMP) || [];
        const existingIdx = tempScans.findIndex(s => s && String(s.productId).toUpperCase() === String(productId).toUpperCase() && s.month === targetMonth);
        if (existingIdx >= 0) {
            tempScans[existingIdx] = newScan;
        } else {
            tempScans.push(newScan);
        }
        this.save(this.KEYS.INV_SCAN_TEMP, JSON.parse(JSON.stringify(tempScans)));

        // 3. INV_LOGS 側にも保存
        this.add(this.KEYS.INV_LOGS, newScan);
    },

    deleteTempScan(scanId) {
        this.delete(this.KEYS.INV_LOGS, scanId);
    },

    clearTempScans() {
        const tempScans = this.getTempScans();
        tempScans.forEach(scan => {
            if (scan && scan.id) {
                this.delete(this.KEYS.INV_LOGS, scan.id);
            }
        });
    },

    // ========================================
    // 棚卸バッチスキャン（オフライン・ローカル蓄積用）
    // ========================================
    LOCAL_BATCH_KEY: 'pms_local_batch_scans',

    getLocalBatchScans() {
        try {
            const data = localStorage.getItem(this.LOCAL_BATCH_KEY);
            return data ? JSON.parse(data) : [];
        } catch (e) {
            console.error('ローカルバッチ読み込みエラー', e);
            return [];
        }
    },

    saveLocalBatchScan(scanItem) {
        const scans = this.getLocalBatchScans();
        scans.push(scanItem);
        localStorage.setItem(this.LOCAL_BATCH_KEY, JSON.stringify(scans));
    },

    updateLocalBatchScan(productId, newQty) {
        const scans = this.getLocalBatchScans();
        // 最新のものを上書きする（通常はproductIdごとに1件を想定）
        let found = false;
        for (let i = scans.length - 1; i >= 0; i--) {
            if (scans[i].productId === productId) {
                scans[i].quantity = newQty;
                scans[i].timestamp = new Date().toISOString();
                found = true;
                break;
            }
        }
        if (found) {
            localStorage.setItem(this.LOCAL_BATCH_KEY, JSON.stringify(scans));
            return true;
        }
        return false;
    },

    deleteLocalBatchScan(productId) {
        let scans = this.getLocalBatchScans();
        // IDが完全一致するものを除外。また、productId自体が存在しない不正なデータもついでに掃除する
        scans = scans.filter(s => s && s.productId && String(s.productId) !== String(productId));
        localStorage.setItem(this.LOCAL_BATCH_KEY, JSON.stringify(scans));
    },

    clearLocalBatchScans() {
        localStorage.setItem(this.LOCAL_BATCH_KEY, JSON.stringify([]));
    },

    // 追加（競合回避：トランザクション使用から全体同期へ変更）
    add(key, newItem) {
        // 即座にローカルに反映してリロード消失を防止
        let localData = this._cache[key] || [];
        if (!Array.isArray(localData)) localData = Object.values(localData).filter(item => item !== null);
        if (newItem.id && !localData.some(d => d.id === newItem.id)) {
            localData.push(newItem);
            this._cache[key] = localData;
            localStorage.setItem(key, typeof LZString !== 'undefined' ? LZString.compressToUTF16(JSON.stringify(localData)) : JSON.stringify(localData));
        }

        // Firebaseの配列処理インデックスずれを防ぐため、全体を保存
        this.save(key, localData);
    },

    // 複数件の追加を安全に行う（競合回避のための update 使用）
    addMultiple(key, newItems) {
        if (!newItems || newItems.length === 0) return Promise.resolve(true);
        
        let localData = this._cache[key] || [];
        if (!Array.isArray(localData)) localData = Object.values(localData).filter(item => item !== null);
        
        newItems.forEach(newItem => {
            if (newItem.id && !localData.some(d => d.id === newItem.id)) {
                localData.push(newItem);
            }
        });
        this._cache[key] = localData;
        localStorage.setItem(key, typeof LZString !== 'undefined' ? LZString.compressToUTF16(JSON.stringify(localData)) : JSON.stringify(localData));

        if (typeof useFirebase !== 'undefined' && useFirebase && firebaseDB && key !== this.KEYS.CURRENT_USER) {
            const fbKey = this.toFirebaseKey(key);
            
            // ルールによるPermission Deniedやレートリミットを防ぐため、直列（1件ずつ順番に）set() を実行する
            const processSequentially = async () => {
                for (const item of newItems) {
                    // Firebaseでは undefined なプロパティはエラーになるため削除
                    Object.keys(item).forEach(k => item[k] === undefined && delete item[k]);
                    
                    await new Promise((resolve, reject) => {
                        firebaseDB.ref(fbKey).child(item.id).set(item, (error) => {
                            if (error) {
                                console.error('Firebase set error for item:', item.id, error);
                                reject(error);
                            } else {
                                resolve();
                            }
                        });
                    });
                }
            };

            return processSequentially()
                .then(() => true)
                .catch(error => {
                    console.error('addMultiple failed (sequential set):', error);
                    toast('データの送信に一部失敗しました: ' + (error.message || error), 'error');
                    return Promise.reject(error);
                });
        } else {
            this.save(key, localData);
            return Promise.resolve(true);
        }
    },

    // 一括追加（Promise対応・Firebase非同期対応）
    addBulk(key, newItems) {
        if (!newItems || newItems.length === 0) return Promise.resolve(true);
        
        console.log(`📦 addBulk開始: key=${key}, 件数=${newItems.length}`);
        
        // 現在のデータを取得してローカルで結合
        const currentData = this.get(key);
        console.log(`📦 addBulk: 既存データ ${currentData.length}件`);
        
        // 最大IDを算出（数値IDのみ対象）
        let maxId = 0;
        currentData.forEach(item => {
            if (item && item.id) {
                const numId = typeof item.id === 'number' ? item.id : parseInt(item.id, 10);
                if (!isNaN(numId) && numId > maxId) maxId = numId;
            }
        });
        console.log(`📦 addBulk: 現在の最大ID=${maxId}`);
        
        // 新アイテムにIDを付与してコピー（元データを変更しない）
        const itemsToAdd = newItems.map(item => {
            maxId++;
            return Object.assign({}, item, { id: maxId });
        });
        
        // 結合
        const merged = currentData.concat(itemsToAdd);
        console.log(`📦 addBulk: 結合後 ${merged.length}件, Firebase=${typeof useFirebase !== 'undefined' && useFirebase}`);
        
        // Firebase使用時は直接setして完了を待つ
        if (typeof useFirebase !== 'undefined' && useFirebase && firebaseDB && key !== this.KEYS.CURRENT_USER) {
            const fbKey = this.toFirebaseKey(key);
            this._cache[key] = merged;
            localStorage.setItem(key, typeof LZString !== 'undefined' ? LZString.compressToUTF16(JSON.stringify(merged)) : JSON.stringify(merged));
            return firebaseDB.ref(fbKey).set(merged)
                .then(() => {
                    console.log(`✅ addBulk Firebase保存完了: ${itemsToAdd.length}件追加`);
                    return true;
                })
                .catch(err => {
                    console.error(`❌ addBulk Firebase保存エラー:`, err);
                    throw err;
                });
        } else {
            // ローカルストレージ
            try {
                localStorage.setItem(key, typeof LZString !== 'undefined' ? LZString.compressToUTF16(JSON.stringify(merged)) : JSON.stringify(merged));
                console.log(`✅ addBulk ローカル保存完了: ${itemsToAdd.length}件追加`);
                return Promise.resolve(true);
            } catch (err) {
                console.error('addBulk ローカル保存エラー:', err);
                return Promise.reject(err);
            }
        }
    },

    // 更新（競合回避：全体同期へ変更）
    update(key, id, updatedItem) {
        // 即座にローカルに反映してリロード消失を防止
        let localData = this._cache[key] || [];
        if (!Array.isArray(localData)) localData = Object.values(localData).filter(item => item !== null);
        const index = localData.findIndex(item => item && item.id === id);
        if (index !== -1) {
            localData[index] = updatedItem;
            this._cache[key] = localData;
            localStorage.setItem(key, typeof LZString !== 'undefined' ? LZString.compressToUTF16(JSON.stringify(localData)) : JSON.stringify(localData));
        }

        // Firebaseの配列処理インデックスずれを防ぐため、全体を保存
        this.save(key, localData);
    },

    // 削除（競合回避：全体同期へ変更）
    delete(key, id) {
        // 即座にローカルに反映してリロード消失を防止
        let localData = this._cache[key] || [];
        if (!Array.isArray(localData)) localData = Object.values(localData).filter(item => item !== null);
        const filteredLocal = localData.filter(item => item && item.id !== id);
        this._cache[key] = filteredLocal;
        localStorage.setItem(key, typeof LZString !== 'undefined' ? LZString.compressToUTF16(JSON.stringify(filteredLocal)) : JSON.stringify(filteredLocal));

        // Firebaseの配列処理インデックスずれを防ぐため、全体を保存
        this.save(key, filteredLocal);
    },

    // 取得
    get(key) {
        // Firebase使用時（ロード完了している場合はキャッシュから取得）
        if (typeof useFirebase !== 'undefined' && useFirebase && key !== this.KEYS.CURRENT_USER) {
            if (this._loaded[key]) {
                return this._cache[key] || [];
            }
        }
        // 未ロード、オフライン時、またはローカル専用時はローカルストレージから取得
        let data = localStorage.getItem(key);
        if (data && !data.startsWith('[') && !data.startsWith('{')) {
            try {
                if (typeof LZString !== 'undefined') {
                    const decompressed = LZString.decompressFromUTF16(data);
                    if (decompressed) data = decompressed;
                }
            } catch(e) {
                console.warn('LZString decompress failed for', key);
            }
        }
        try {
            const parsed = data ? JSON.parse(data) : [];
            const parsedArray = Array.isArray(parsed) ? parsed : [];
            return parsedArray.filter(item => item !== null);
        } catch (e) {
            console.error('DB Parse Error:', key, e);
            return [];
        }
    },

    // 次のID
    nextId(key) {
        const data = this.get(key);
        return data.length > 0 ? Math.max(...data.map(d => d.id || 0)) + 1 : 1;
    },

    // ========================================
    // バックアップ機能
    // ========================================

    // バックアップ対象のキー一覧
    _backupTargetKeys() {
        return [
            this.KEYS.USERS, this.KEYS.BOM, this.KEYS.ORDERS,
            this.KEYS.RATES, this.KEYS.DEFECTS, this.KEYS.PROGRESS_HISTORY,
            this.KEYS.INV_PRODUCTS, this.KEYS.INV_LOGS, this.KEYS.INV_MONTHLY,
            this.KEYS.NOTICE
        ];
    },

    // バックアップ作成
    createBackup(label) {
        const snapshot = {};
        let totalRecords = 0;
        this._backupTargetKeys().forEach(key => {
            const data = this.get(key);
            snapshot[key] = data;
            totalRecords += data.length;
        });

        const backups = this.get(this.KEYS.BACKUPS);
        const backup = {
            id: Date.now(),
            label: label || '手動バックアップ',
            createdAt: new Date().toISOString(),
            totalRecords,
            dataSize: JSON.stringify(snapshot).length,
            snapshot
        };
        backups.push(backup);
        this.save(this.KEYS.BACKUPS, backups);
        localStorage.setItem('pms_last_backup_date', new Date().toISOString());
        return backup;
    },

    // バックアップから復元
    restoreBackup(backupId) {
        const backups = this.get(this.KEYS.BACKUPS);
        const backup = backups.find(b => b.id === backupId);
        if (!backup || !backup.snapshot) return false;

        this._backupTargetKeys().forEach(key => {
            if (backup.snapshot[key] !== undefined) {
                this.save(key, backup.snapshot[key]);
            }
        });
        return true;
    },

    // バックアップ削除
    deleteBackupById(backupId) {
        let backups = this.get(this.KEYS.BACKUPS);
        backups = backups.filter(b => b.id !== backupId);
        this.save(this.KEYS.BACKUPS, backups);
    },

    // バックアップ一覧取得(スナップショットなし=軽量)
    getBackupList() {
        const backups = this.get(this.KEYS.BACKUPS);
        return backups.map(b => ({
            id: b.id,
            label: b.label,
            createdAt: b.createdAt,
            totalRecords: b.totalRecords,
            dataSize: b.dataSize
        }));
    },

    // 自動バックアップチェック（月1回・日曜日）
    checkAutoBackup() {
        const now = new Date();
        // 日曜日（0）でなければスキップ
        if (now.getDay() !== 0) return;

        const lastBackup = localStorage.getItem('pms_last_backup_date');
        if (lastBackup) {
            const lastDate = new Date(lastBackup);
            const daysSince = (now - lastDate) / (1000 * 60 * 60 * 24);
            if (daysSince < 28) return; // 28日未満ならスキップ
        }

        // 自動バックアップ実行
        console.log('💾 自動バックアップを実行中...');
        const backup = this.createBackup('自動バックアップ（月次）');
        console.log(`✅ 自動バックアップ完了: ${backup.totalRecords}件`);
        if (typeof toast === 'function') {
            toast(`💾 月次自動バックアップを作成しました（${backup.totalRecords}件）`, 'success');
        }

        // 古いバックアップを整理（最新6件のみ保持）
        let backups = this.get(this.KEYS.BACKUPS);
        if (backups.length > 6) {
            backups.sort((a, b) => b.id - a.id);
            backups = backups.slice(0, 6);
            this.save(this.KEYS.BACKUPS, backups);
        }
    },
    // BOM強制アップデート (v6.00) & 棚卸原簿マスタ移行 (v6.81)
    applyLatestBom() {
        if (localStorage.getItem('pms_bom_v503_applied') !== 'true') {
            console.log('🔄 v6.00の最新BOMデータを強制適用します...');
            this.save(this.KEYS.BOM, NEW_BOM_DATA);
            localStorage.setItem('pms_bom_v503_applied', 'true');
        }
        if (typeof this.applyLatestGenboMaster === 'function') {
            this.applyLatestGenboMaster();
        }
    },

    // 棚卸原簿.xlsx & 資材コード一覧及び棚卸対象一覧.xlsx マスタ一括移行 ＆ 10月期(AK列)初期締め処理（v6.83.0）
    applyLatestGenboMaster(forceReplace = false) {
        if (typeof getGenboMasterProducts !== 'function') return;
        // Firebaseモードでは、INV_PRODUCTS / INV_MONTHLY / INV_LOGS / INV_SCAN_TEMP の全4キー読込完了を必ず待つ
        if (typeof useFirebase !== 'undefined' && useFirebase && (
            !this._loaded[this.KEYS.INV_PRODUCTS] ||
            !this._loaded[this.KEYS.INV_MONTHLY] ||
            !this._loaded[this.KEYS.INV_LOGS] ||
            !this._loaded[this.KEYS.INV_SCAN_TEMP]
        )) {
            setTimeout(() => this.applyLatestGenboMaster(forceReplace), 1000);
            return;
        }
        const currentProducts = this.get(this.KEYS.INV_PRODUCTS) || [];
        const currentMonthly = this.get(this.KEYS.INV_MONTHLY) || [];
        const octRecord = currentMonthly.find(m => m && m.month === '2026-10');
        const fixedCount = currentProducts.filter(p => p && p.isFixed).length;
        const alreadyApplied = localStorage.getItem('pms_genbo_v683_oct_closed') === 'true';

        // 実際に10月期締めデータが存在し、かつ不動品数が正常(コード4のみ=74件付近)である場合のみスキップ
        const isDataHealthy = (
            currentProducts.length >= 3000 &&
            fixedCount <= 120 &&
            !!octRecord &&
            octRecord.isInitialBaseline === true &&
            Number(octRecord.total) > 0 &&
            Number(octRecord.fixedTotal) < Number(octRecord.total) * 0.2
        );
        if (alreadyApplied && !forceReplace && isDataHealthy) {
            return;
        }

        console.log('🔄 棚卸原簿.xlsx マスタデータ(3,104件)の移行および10月期(AK列)初期締め処理を実行します...');
        const genboProducts = getGenboMasterProducts();

        // 既存データのマップ構築（資材コード・識別コード・IDで照合し、価格更新履歴や11月期以降の仮スキャンを保持）
        const existingByKey = new Map();
        currentProducts.forEach(p => {
            if (!p) return;
            if (p.id) existingByKey.set(String(p.id).trim().toUpperCase(), p);
            if (p.identCode) existingByKey.set(String(p.identCode).trim().toUpperCase(), p);
            if (p.materialCode) existingByKey.set(String(p.materialCode).trim().toUpperCase(), p);
        });

        const matchedExistingIds = new Set();
        const mergedProducts = genboProducts.map(gp => {
            const ex = existingByKey.get(String(gp.id).toUpperCase())
                || existingByKey.get(String(gp.identCode).toUpperCase())
                || existingByKey.get(String(gp.materialCode).toUpperCase());

            // 月締めで表示（集計）する不動品在庫は、棚卸対象コード4のみ
            const isTarget4Fixed = (Number(gp.targetFlag) === 4);
            // 10月期のデータは棚卸原簿AK列(octStock)を活用して初期値とする
            const octInitialStock = Number(gp.octStock) || 0;

            if (ex) {
                if (ex.id) matchedExistingIds.add(String(ex.id).toUpperCase());
                if (ex.identCode) matchedExistingIds.add(String(ex.identCode).toUpperCase());
                if (ex.materialCode) matchedExistingIds.add(String(ex.materialCode).toUpperCase());

                const merged = Object.assign({}, gp, {
                    isFixed: isTarget4Fixed,
                    stock: octInitialStock,
                    lastStock: octInitialStock,
                    inventoryDate: octInitialStock > 0 ? '2026-10-31T23:59:59.000Z' : ''
                });

                // 11月期(2026-11)以降の進行中の仮スキャンデータがあれば保持（10月期以前はリセットして11月期から新規収集）
                if (ex.tempQty !== undefined && ex.tempQty !== null && ex.tempMonth && ex.tempMonth >= '2026-11') {
                    merged.tempQty = ex.tempQty;
                    merged.tempWorker = ex.tempWorker;
                    merged.tempWorkerName = ex.tempWorkerName;
                    merged.tempTimestamp = ex.tempTimestamp;
                    merged.tempMonth = ex.tempMonth;
                    merged.tempId = ex.tempId;
                    if (ex.tempAmountWithTax !== undefined) merged.tempAmountWithTax = ex.tempAmountWithTax;
                }
                if (Array.isArray(ex.priceHistory) && ex.priceHistory.length > 0) {
                    merged.priceHistory = ex.priceHistory.slice();
                }
                if (ex.price !== undefined && Number(ex.price) > 0 && Number(ex.price) !== Number(gp.price)) {
                    const todayStr = gp.priceUpdatedAt || new Date().toISOString().split('T')[0];
                    if (!Array.isArray(merged.priceHistory)) merged.priceHistory = [];
                    merged.priceHistory.unshift({
                        date: todayStr,
                        timestamp: new Date().toISOString(),
                        oldPrice: Number(ex.price),
                        newPrice: Number(gp.price),
                        updatedBy: 'システム同期',
                        reason: '棚卸原簿マスタ入替'
                    });
                }
                if (ex.priceUpdatedAt && (!merged.priceUpdatedAt || ex.priceUpdatedAt > merged.priceUpdatedAt)) {
                    merged.priceUpdatedAt = ex.priceUpdatedAt;
                }
                return merged;
            }
            return gp;
        });

        // 棚卸原簿に存在しないが、システム上で独自追加されたカスタム資材があれば末尾に保持（サンプル3件やTEMP_は除外）
        const sampleIds = new Set(['N01000000001', 'N02000000001', 'N05000000001']);
        currentProducts.forEach(ex => {
            if (!ex || !ex.id) return;
            const uid = String(ex.id).trim().toUpperCase();
            if (uid.startsWith('TEMP_') || sampleIds.has(uid)) return;
            const uIdent = ex.identCode ? String(ex.identCode).trim().toUpperCase() : '';
            const uMat = ex.materialCode ? String(ex.materialCode).trim().toUpperCase() : '';
            if (!matchedExistingIds.has(uid) && (!uIdent || !matchedExistingIds.has(uIdent)) && (!uMat || !matchedExistingIds.has(uMat))) {
                if (ex.isCustomAdded) {
                    ex.isFixed = (Number(ex.targetFlag) === 4);
                    mergedProducts.push(ex);
                }
            }
        });

        const pProd = this.save(this.KEYS.INV_PRODUCTS, JSON.parse(JSON.stringify(mergedProducts)));
        const octRes = this.initializeOctoberGenboClosing(mergedProducts);
        const allPromises = [pProd, ...(octRes && octRes.savePromises ? octRes.savePromises : [])];

        Promise.all(allPromises).then((results) => {
            if (results.includes(false)) {
                console.warn('⚠️ 一部のデータ保存が未完了のため、1秒後にリトライします...');
                setTimeout(() => this.applyLatestGenboMaster(true), 1000);
                return;
            }
            localStorage.setItem('pms_genbo_v681_applied', 'true');
            localStorage.setItem('pms_genbo_v682_oct_closed', 'true');
            localStorage.setItem('pms_genbo_v683_oct_closed', 'true');
            console.log(`✅ 棚卸原簿マスタ移行＆10月期(2026-10)初期締め保存完了: 全 ${mergedProducts.length} 件`);
            if (typeof refreshCurrentPage === 'function') refreshCurrentPage();
        }).catch(err => {
            console.error('❌ 棚卸原簿マスタ移行エラー:', err);
        });
    },

    // 棚卸原簿.xlsx のAK列（10月度棚卸数量）を活用した10月期(2026-10)の集計・締め処理（在庫管理の初期データ化＆11月期収集開始）
    initializeOctoberGenboClosing(productsList = null) {
        const products = productsList || this.get(this.KEYS.INV_PRODUCTS) || [];
        if (products.length === 0) return null;

        const GENBO_CAT_NAMES = {
            '01': '基材', '02': '面材', '03': 'シート', '04': '木口ﾃｰﾌﾟ', '05': '金具',
            '06': 'ﾀﾞﾝﾎﾞｰﾙ', '07': '接着剤', '08': '仕入備品', '09': 'PAO資材', '10': '工場部材',
            '11': '仕掛品芯組のみ', '12': '仕掛品カット', '13': '部材完成品', '14': '製品在庫',
            '15': 'シェルフ製品在庫', '16': 'キャビネット製品在庫', '17': 'ラミテック', '18': '天野木工',
            '19': 'いろは', '20': 'Real', '21': 'イイダアックス', '22': '下請け預かり品',
            '23': 'GRID不動品', '24': '仕掛品フラッシュのみ', '25': '仕掛品(Tpics)',
            '26': '仕掛品(未完成品)', '27': '入荷品'
        };

        const targetMonth = '2026-10';
        const octTimestamp = '2026-10-31T23:59:59.000Z';
        const sortedProducts = [...products].sort((a, b) => String(a.id || '').localeCompare(String(b.id || '')));

        const octItems = [];
        const octSummary = {};
        const octLogs = [];
        let rawTotal = 0;

        sortedProducts.forEach((p, idx) => {
            if (!p || !p.id) return;
            const octQty = Number(p.octStock !== undefined ? p.octStock : p.stock) || 0;
            const price = Number(p.price) || 0;
            // 月締めで表示（集計）する不動品在庫は、棚卸対象コード4のみ集計
            const isFixed = (Number(p.targetFlag) === 4);
            const rawAmount = octQty * price * 1.01;
            const amount = Math.round(rawAmount);
            const cat = String(p.category || '99').padStart(2, '0');

            p.stock = octQty;
            p.lastStock = octQty;
            p.isFixed = isFixed;

            octItems.push({
                productId: p.id,
                identCode: p.identCode || p.id,
                name: p.name,
                category: cat,
                targetFlag: Number(p.targetFlag) || 0,
                price: price,
                prevQty: 0,
                currQty: octQty,
                diff: octQty,
                amount: amount,
                prevAmount: 0,
                rawAmount: rawAmount,
                rawPrevAmount: 0,
                isFixed: isFixed
            });

            rawTotal += amount;

            const catKey = isFixed ? 'fixed' : cat;
            if (!octSummary[catKey]) {
                const catName = isFixed ? '不動品' : (GENBO_CAT_NAMES[cat] || p.categoryName || `分類${cat}`);
                octSummary[catKey] = { name: catName, rawAmount: 0, rawPrevAmount: 0, amount: 0, diff: 0, prevAmount: 0 };
            }
            octSummary[catKey].rawAmount += amount;

            if (octQty > 0) {
                octLogs.push({
                    id: 1730386799000 + idx,
                    productId: p.id,
                    quantity: octQty,
                    type: 'count',
                    worker: '初期データ(棚卸原簿AK列)',
                    note: '10月期初期在庫確定(2026-10 棚卸原簿AK列)',
                    timestamp: octTimestamp
                });
            }
        });

        const total = Math.round(rawTotal);
        let largestCatKey = null;
        let maxCatRawAmt = -1;

        Object.keys(octSummary).forEach(k => {
            const amt = Math.round(octSummary[k].rawAmount || 0);
            octSummary[k].amount = amt;
            octSummary[k].prevAmount = 0;
            octSummary[k].diff = amt;
            if ((octSummary[k].rawAmount || 0) > maxCatRawAmt) {
                maxCatRawAmt = octSummary[k].rawAmount || 0;
                largestCatKey = k;
            }
        });

        const catSum = Object.values(octSummary).reduce((s, c) => s + c.amount, 0);
        const catDiff = total - catSum;
        if (catDiff !== 0 && largestCatKey && octSummary[largestCatKey]) {
            octSummary[largestCatKey].amount += catDiff;
            octSummary[largestCatKey].diff = octSummary[largestCatKey].amount;
        }

        const fixedTotal = (octSummary['fixed'] ? octSummary['fixed'].amount : 0) || 0;

        const octMonthlyData = {
            month: targetMonth,
            items: octItems,
            summary: octSummary,
            total: total,
            prevTotal: 0,
            fixedTotal: fixedTotal,
            closedAt: octTimestamp,
            isInitialBaseline: true
        };

        // 1. INV_MONTHLY: 旧マスタ時代の10月期以前のデータを整理し、2026-10(10月期)を初期締めデータとして保存（2026-11以降があれば維持）
        const existingMonthly = this.get(this.KEYS.INV_MONTHLY) || [];
        const futureMonthly = existingMonthly.filter(m => m && m.month && m.month > targetMonth);
        const newMonthlyList = [octMonthlyData, ...futureMonthly].sort((a, b) => a.month.localeCompare(b.month));
        const pMonthly = this.save(this.KEYS.INV_MONTHLY, JSON.parse(JSON.stringify(newMonthlyList)));

        // 2. INV_LOGS: 2026-10以前の旧ログをクリアし、10月期確定ログ＋2026-11以降のログのみを保持
        const existingLogs = this.get(this.KEYS.INV_LOGS) || [];
        const futureLogs = existingLogs.filter(l => l && l.timestamp && l.timestamp >= '2026-11');
        const pLogs = this.save(this.KEYS.INV_LOGS, JSON.parse(JSON.stringify([...octLogs, ...futureLogs])));

        // 3. INV_SCAN_TEMP: 2026-10以前の仮スキャンをクリアし、2026-11(11月期)からの新規収集状態にする
        const existingTempScans = this.get(this.KEYS.INV_SCAN_TEMP) || [];
        const futureTempScans = existingTempScans.filter(s => s && s.month && s.month >= '2026-11');
        const pTemp = this.save(this.KEYS.INV_SCAN_TEMP, JSON.parse(JSON.stringify(futureTempScans)));

        return { octMonthlyData, savePromises: [pMonthly, pLogs, pTemp] };
    }
};

