function getGenboMasterProducts() {
    return MASTER_GENBO_RAW.map(r => {
        const targetFlag = Number(r[16]) || 0;
        const discFlag = Number(r[17]) || 0;
        // 月締めで表示（集計）する不動品在庫は、棚卸対象コード4のみ
        const isFixed = (targetFlag === 4);
        const isDeadStock = (discFlag === 1) || (targetFlag === 4);
        const isTarget = !(targetFlag === 0 || targetFlag === 7);
        const deadQty = Number(r[18]) || 0;
        const prevQty = Number(r[19]) || 0;
        // AK列には10月期の棚卸集計結果が記載されているため、これを初期値とする
        const octQty = Number(r[36]) || 0;
        const cleanName = String(r[8] || "").replace(/[\r\n]+/g, " ").trim();
        return {
            id: r[4],
            identCode: r[0],
            identClass: r[1],
            identOrder: r[2],
            category: r[1],
            categoryName: r[3] || "",
            materialCode: r[4],
            materialType: r[5] || "直接資材",
            subCategory: r[6] || "",
            note: r[7] || "",
            name: cleanName,
            colorOther: r[9] || "",
            composition: r[10] || "",
            material: r[10] || "",
            width: r[11] || "",
            length: r[12] || "",
            thickness: r[13] || "",
            unit: r[14] || "",
            price: Number(r[15]) || 0,
            targetFlag: targetFlag,
            discontinuedFlag: discFlag,
            isDeadStock: isDeadStock,
            isFixed: isFixed,
            isTarget: isTarget,
            deadStockQty: deadQty,
            prevStock: prevQty,
            octStock: octQty,
            stock: octQty,
            lastStock: octQty,
            inventoryDate: octQty > 0 ? "2026-10-31T23:59:59.000Z" : "",
            updatedAt: r[20] || "",
            priceUpdatedAt: r[20] || "",
            orderProductName: r[21] || "",
            supplier: r[22] || "",
            supplierCode: r[23] || "",
            orderLot: r[24] || "",
            leadTime: r[25] || "",
            stockPartNo: r[26] || "",
            customerName: r[27] || "",
            siteName: r[28] || "",
            requestNo: r[29] || "",
            partNo: r[30] || "",
            processName: r[31] || "",
            orderNo: r[32] || "",
            progressRate: r[33] || "",
            branchNo: r[34] || "",
            requestBranchNo: r[35] || ""
        };
    });
}
